import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"RFC Index","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/rfcs/README.md"},"headers":[],"relativePath":"sovereign-os/rfcs/README.md","filePath":"sovereign-os/rfcs/README.md"}'),o={name:"sovereign-os/rfcs/README.md"};function r(s,e,c,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="rfc-index" tabindex="-1">RFC Index <a class="header-anchor" href="#rfc-index" aria-label="Permalink to &quot;RFC Index&quot;">​</a></h1><p>RFCs are proposals, not decisions. Start with the <a href="./../templates/rfc.html">RFC template</a>, use zero-padded sequential identifiers, and do not mark an RFC Accepted without project-owner approval.</p><h2 id="initial-preview-backlog" tabindex="-1">Initial Preview Backlog <a class="header-anchor" href="#initial-preview-backlog" aria-label="Permalink to &quot;Initial Preview Backlog&quot;">​</a></h2><ul><li>RFC-0001: Monorepo structure</li><li><a href="./0002-local-conversation-and-inference-runtime.html">RFC-0002: Local conversation and inference runtime architecture</a> - Accepted</li><li><a href="./0003-capability-contract.html">RFC-0003: Capability contract</a> - Accepted</li><li><a href="./0004-ai-capability-invocation.html">RFC-0004: AI capability invocation</a> - Accepted</li><li><a href="./0010-raspberry-pi-image-deployment.html">RFC-0010: Raspberry Pi image deployment</a> - Proposed</li><li><a href="./0006-pihole-capability-mapping.html">RFC-0006: Pi-hole capability mapping</a> - Accepted</li><li><a href="./0014-appliance-update-system.html">RFC-0014: Appliance update system</a> - Implemented</li><li><a href="./0015-update-discovery.html">RFC-0015: Update discovery - channel metadata and device-side checking</a> - Accepted</li><li><a href="./0016-full-base-os-updates.html">RFC-0016: Full base-OS updates (A/B root filesystem)</a> - Accepted</li><li><a href="./0017-web-search-and-fetch-capability-mapping.html">RFC-0017: web.search and web.fetch capability mapping</a> - Accepted</li><li><a href="./0018-home-assistant-read-only-capability-mapping.html">RFC-0018: Home Assistant read-only capability mapping</a> - Accepted</li><li><a href="./0019-home-assistant-allowlisted-action-capability-mapping.html">RFC-0019: Home Assistant allowlisted-action capability mapping</a> - Accepted</li></ul><p>RFC-0001 refers to earlier platform work and remains unwritten; create it only when its problem and evidence are mature enough for a concrete proposal. Later proposals for authentication, configuration, logging, backup, general plugin lifecycle, and voice follow the same rule.</p><p>RFC-0002 through RFC-0004 and RFC-0006 are the proposal set required for <a href="./../roadmap/01-2-local-conversation-capabilities.html">Milestone 01.2</a>, and all four are now Accepted (2026-08-09, project creator). Implementation must preserve the accepted appliance and update boundaries. <a href="./../research/pihole-api-assessment.html">docs/research/pihole-api-assessment.md</a>&#39;s empirical investigation against the real pinned Pi-hole version, RFC-0006&#39;s remaining prerequisite, concluded 2026-08-09 with a real, live-verified authenticated round trip on the qualification device. Implementation begins next.</p><p>RFC-0017 is the milestone&#39;s remaining required document (<code>web.search</code> privacy design), drafted 2026-08-21 against <a href="./../research/searxng-deployment-assessment.html">docs/research/searxng-deployment-assessment.md</a> and the confirmation-flow/policy-state gaps already visible in <code>sovereign_conversation.py</code>. Implemented and hardware-qualified before formal review (this project&#39;s own precedent), then reviewed and accepted 2026-08-21 — the review found and fixed one real piece of drift (a resolved Unresolved Question that was still marked open) rather than re-approving the text unchanged.</p><p>RFC-0018 is Milestone 5&#39;s first document (Home Assistant read-only entity/ history capability mapping), drafted 2026-08-21 against RFC-0017&#39;s already-shipped confirmation wire format and Home Assistant&#39;s own REST API documentation, and accepted the same day after review found and fixed a stage-numbering inconsistency and a disclosed, non-blocking TLS gap. Implementation (capability, executor generalization, and Console settings UI) shipped the same day, real-hardware qualification blocked on no Home Assistant instance existing on the household network yet.</p><p>RFC-0019 is Milestone 5&#39;s second document (the allowlisted-action slice — <code>home_assistant.set_entity_state</code>, scoped to <code>light</code>/<code>switch</code> only), drafted 2026-08-21 against RFC-0003/RFC-0004&#39;s shared, on-the-record deferral of mutating-capability confirmation UX to whichever RFC ships the first mutating capability. Accepted the same day after review found and fixed a real gap: domain scope was claimed to be enforced at three points but only one was actually designed — closed by adding two independent domain re-checks, since Home Assistant&#39;s <code>climate</code> domain turns out to have real <code>turn_on</code>/<code>turn_off</code> services that wouldn&#39;t have failed safely by accident.</p>',9)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
